import sys

def lis(seq):
    if not seq:
        return 0
    dp = [1] * len(seq)
    for i in range(1, len(seq)):
        for j in range(i):
            if seq[i] >= seq[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def solve(s):
    n = len(s)
    t = ['0'] * n
    for i in range(n):
        if lis(s[:i+1]) != lis(t[:i+1]):
            t[i] = '1'
    return ''.join(t)

s = sys.stdin.read().strip()
print(solve(s))
